"""Material library.

Each entry is either
  * a textured material (has "family" -> generated by textures.py), with
    bay / fh = metres covered by one texture cell horizontally / vertically,
    cx / cy = number of cells in the texture, or
  * a flat colour material (no "family").
"""

# metres covered by one plain-texture tile so brick scale matches facades
PLAIN_M = 8.8

BRICKS = {
    "red": (150, 62, 48),
    "brown": (110, 62, 45),
    "tan": (190, 160, 120),
    "yellow": (205, 180, 120),
    "gray": (130, 128, 125),
    "white": (215, 210, 200),
    "orange": (175, 90, 55),
    "dark": (80, 50, 42),
}


def W(color, wall="brick", **kw):
    d = dict(family="windows", color=color, wall=wall, bay=3.0, fh=3.3, cx=4, cy=4,
             roughness=0.85)
    d.update(kw)
    return d


def P(color, wall="smooth", size_m=PLAIN_M, **kw):
    d = dict(family="plain", color=color, wall=wall, bay=size_m, fh=size_m, cx=1, cy=1,
             roughness=0.9)
    d.update(kw)
    return d


def F(color, roughness=0.6, metallic=0.0, emission=None):
    return dict(color=color, roughness=roughness, metallic=metallic, emission=emission,
                bay=1, fh=1, cx=1, cy=1)


MATERIALS = {}

# ---- brick facades (windows) -------------------------------------------------
for k, c in BRICKS.items():
    MATERIALS[f"brick_{k}"] = W(c, lintel=(205, 198, 185))
    MATERIALS[f"brick_{k}_blank"] = P(c, "brick")

